const D = { energy:.6, density:.5, scale:1, speed:1, hue:342, petals:8, x:.5, y:.56, style:'plate', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---- Flowers opening by differential growth rather than by keyframe: the adaxial surface
// outgrows the abaxial until each petal's curvature reverses through zero and the bud reflexes
// itself open. A DENSE PLATE of 16 staggered blooms on a ~40s cycle — bud, anthesis, turgor loss,
// abscission, bare receptacle, new bud — so something is always opening and something always
// shedding; the sheet never converges and never empties. Herbarium rigour, not a cartoon flower:
// ink line, stipple modelling, sepals, androecium, cauline leaves, a ruled specimen sheet.
const cl = (v,a,b) => v<a?a:(v>b?b:v);
const u = Math.min(width, height);
const sd = P.seed|0;
const fr = i => { const s = Math.sin(i*127.1 + sd*311.7) * 43758.5453; return s - Math.floor(s); };
const sty = P.style;
const EN = cl(P.energy,0,1), DN = cl(P.density,0,1), SC = cl(P.scale,.35,2.2);
const NP = Math.round(cl(P.petals,3,13)), AL = cl(P.alpha,0,100)/100;

if (S.lastT == null || K.t < S.lastT) S.lastT = K.t;
let dt = K.t - S.lastT; S.lastT = K.t;
if (!(dt >= 0) || dt > .25) dt = 1/60;
const SP = cl(P.speed,.05,4);
S.tt = (S.tt || 0) + dt*SP;
const T = S.tt;
const gust = .9*Math.sin(T*.61) + .5*Math.sin(T*1.43+1.7) + .32*Math.sin(T*2.29) + .35*Math.sin(T*.163);
const breeze = (.25 + .85*EN)*gust + A.lowmid*.75 + K.pulse*.2*K.intensity;

// ---- style ---------------------------------------------------------------
const H = P.hue;
let papH, papS, papB, inkH, inkS, inkB, mode;
if (sty === 'cyanotype') { papH = (213 + (H-213)*.16 + 360)%360; papS = 84; papB = 26; inkH = papH; inkS = 4; inkB = 98; mode = 1; }
else if (sty === 'xray') { papH = 198; papS = 44; papB = 15; inkH = H; inkS = 42; inkB = 96; mode = 2; }
else if (sty === 'chiaroscuro') { papH = 26; papS = 48; papB = 13; inkH = H; inkS = 30; inkB = 90; mode = 3; }
else { papH = 40; papS = 16; papB = 54; inkH = 24; inkS = 55; inkB = 17; mode = 0; }

// ---- ground: a ruled specimen sheet --------------------------------------
const bgKey = [width,height,sd,sty,H].join('|');
if (!S.g || S.bgKey !== bgKey) {
  S.bgKey = bgKey;
  const bw = Math.min(620, Math.max(240, width|0));
  const bh = Math.max(1, Math.round(bw*height/Math.max(1,width)));
  const g = (S.g && S.g.width === bw && S.g.height === bh) ? S.g : createGraphics(bw, bh);
  S.g = g; g.colorMode(HSB, 360, 100, 100, 100);
  g.push(); g.noStroke(); g.background(papH, papS, papB);
  if (mode === 1) {
    for (let i=0;i<190;i++){ const w2 = bw*(.25+fr(i*2.9)*.95);
      g.fill(papH, papS-fr(i*4.4)*26, papB + (fr(i*6.6)-.44)*19, 25);
      g.rect(fr(i*8.1)*bw-w2*.3, fr(i*5.3)*bh, w2, bh*.014 + fr(i*9.9)*bh*.022); }
  } else if (mode === 2) {
    for (let i=0;i<2400;i++){ g.fill(196, 30, 44+fr(i*4.4)*46, 8); g.rect(fr(i*3.9)*bw, fr(i*6.1+3)*bh, 1.3, 1.3); }
  } else if (mode === 3) {
    const dc0 = g.drawingContext;                          // a single pool of light
    const lg = dc0.createRadialGradient(bw*.42, bh*.4, bw*.02, bw*.42, bh*.4, bw*.72);
    lg.addColorStop(0, 'rgba(255,238,214,0.30)'); lg.addColorStop(.5, 'rgba(210,180,150,0.09)');
    lg.addColorStop(1, 'rgba(0,0,0,0)'); dc0.fillStyle = lg; dc0.fillRect(0,0,bw,bh);
    for (let i=0;i<2600;i++){ g.fill(28, 40, 30+fr(i*4.1)*46, 7); g.rect(fr(i*3.7)*bw, fr(i*8.3+2)*bh, 1.4, 1.4); }
  } else {
    for (let i=0;i<2800;i++){ g.fill(papH, papS*(.5+fr(i*2.3)), papB + (fr(i*5.1)-.5)*26, 44);
      g.rect(fr(i*3.1)*bw, fr(i*7.7+9)*bh, 1.4, 1.4); }
    for (let i=0;i<18;i++){ const fx=fr(i*13.3+2)*bw, fy=fr(i*17.1+5)*bh, r=bw*(.015+fr(i*3.7)*.05);
      for (let k=0;k<3;k++){ g.fill(24, 46, 40, 5); g.ellipse(fx, fy, r*(1+k*.7), r*(.85+k*.6)); } }
    g.noFill(); g.stroke(inkH, 30, 40, 20); g.strokeWeight(1);        // sheet rule
    g.rect(bw*.03, bh*.04, bw*.94, bh*.92); g.noStroke();
  }
  const dc = g.drawingContext;
  const rg = dc.createRadialGradient(bw*.5, bh*.5, bw*.12, bw*.5, bh*.5, bw*.82);
  rg.addColorStop(0, 'rgba(0,0,0,0)');
  rg.addColorStop(1, mode===3 ? 'rgba(0,0,0,0.55)' : mode===0 ? 'rgba(0,0,0,0.42)' : 'rgba(0,0,0,0.36)');
  dc.fillStyle = rg; dc.fillRect(0, 0, bw, bh);
  g.pop();
}

// ---- flower pool: staggered bud -> anthesis -> wilt -> shed -> bud -------
// 16 blooms on a jittered 4x4 with depth, cycling in ~40s (the first cut ran 6 blooms on a ~74s
// cycle and drew 4 of them: three sparse flowers that had all finished opening. It converged.)
const NMAX = 16;
const ORD = [5,10,0,15,7,2,12,9,4,14,1,11,6,13,3,8];      // spread the drawn subset over the sheet
const TB = 6, TO = 17, TA = 24, TW = 33, TD = 40, TZ = 44;
const reseed = f => {
  const j = f.id*37.1 + (f.gen = (f.gen||0)+1)*13.3;
  const c0 = ORD[f.id];
  f.ox = (.10 + (c0 % 4)*.27 + (fr(j*1.3)-.5)*.15);
  f.oy = (.20 + ((c0/4)|0)*.24 + (fr(j*2.1)-.5)*.13);
  f.dep = .55 + fr(j*1.9)*.85;                 // depth: near blooms bigger, far ones smaller
  f.sz = (.72 + fr(j*3.3)*.62)*f.dep;
  f.tilt = .42 + fr(j*4.7)*.7;                 // view tilt: 0 = face-on, 1.1 = three-quarter
  f.spin = fr(j*5.9)*6.28;
  f.hj = (fr(j*6.3)-.5)*44;
  f.ph = fr(j*7.1)*6.28;
  f.rate = .82 + fr(j*8.9)*.42;
  f.spr = (.07 + fr(j*10.3)*.06)*(f.id%2 ? 1 : -1);        // head rotation, two senses
  f.shed = [];
  for (let k=0;k<13;k++) f.shed.push(fr(j*9.7 + k*3.1));   // per-petal abscission order
  f.age = 0;
};
if (!S.fl || S.fl.length !== NMAX || S.szKey !== width+'x'+height+sd) {
  S.szKey = width+'x'+height+sd; S.fl = [];
  for (let i=0;i<NMAX;i++){ const f = { id:i }; reseed(f); f.age = fr(i*21.3)*TZ; S.fl.push(f); }
}
for (let i=0;i<NMAX;i++){ const f = S.fl[i];
  f.age += dt*SP*f.rate*(.6 + .85*EN)*(.7 + .6*K.intensity);
  if (f.age > TZ) reseed(f); }

// ---- draw ----------------------------------------------------------------
image(S.g, 0, 0, width, height);
const nDraw = cl(Math.round(4 + DN*10), 2, NMAX);
const NSG = 15;                                  // integration steps along the petal
if (mode === 2) blendMode(ADD);
strokeJoin(ROUND); strokeCap(ROUND);
const wprof = s => Math.pow(Math.sin(Math.PI*Math.pow(cl(s,0,1), .72)), .6);
const order2 = [];
for (let n=0;n<nDraw;n++) order2.push(n);
order2.sort((a,b) => S.fl[a].dep - S.fl[b].dep);           // far blooms behind near ones

for (let oi=0;oi<order2.length;oi++) {
  const f = S.fl[order2[oi]]; if (!f) continue;
  const a = f.age;
  const swell = cl(a/TB, 0, 1);
  const opn = cl((a - TB)/(TO - TB), 0, 1);                // 0 = bud, 1 = fully reflexed
  const o = opn*opn*(3 - 2*opn);
  const wilt = cl((a - TA)/(TW - TA), 0, 1);
  const shedP = cl((a - TW)/(TD - TW), 0, 1);
  const R = u*.155*SC*f.sz;                                // petal length at anthesis
  const cx = (f.ox + (P.x-.5))*width, cyy = (f.oy + (P.y-.56))*height;
  const sway = breeze*u*.030*f.sz*(.6 + .7*Math.sin(T*.87 + f.ph));
  const bob = Math.sin(T*1.13 + f.ph*1.9)*u*.008*(.4+EN);
  // the head rotates on its own sense and rate: over 8s this walks each corolla by roughly a
  // whole petal index, which decorrelates the frame without anything jumping.
  const spin = f.spin + T*f.spr;
  const tl = f.tilt, ct = Math.cos(tl), stl = Math.sin(tl);
  const hh = ((P.hue + f.hj + wilt*22) % 360 + 360) % 360;

  push(); translate(cx + sway, cyy + bob);
  // --- stem down out of frame, swaying, with a cauline leaf or two for plate density
  const stH = height - (cyy + bob) + u*.06;
  noFill();
  stroke(mode===1 ? inkH : (mode===2 ? 120 : 96), mode===1?18:52, mode===1?70:(mode===3?28:34), 78*AL);
  strokeWeight(Math.max(1.1, R*.06));
  beginShape();
  for (let q=0;q<=8;q++){ const v = q/8;
    vertex(-sway*v*1.6 + Math.sin(T*.53 + f.ph + v*2.2)*u*.006*v*(.5+EN), stH*v); }
  endShape();
  for (let q=0;q<2;q++){
    const v = .30 + q*.26, sg = q%2 ? 1 : -1;
    const lx = -sway*v*1.6 + Math.sin(T*.53 + f.ph + v*2.2)*u*.006*v*(.5+EN), ly = stH*v;
    const LL = R*(.42 + .2*fr(f.id*3.7+q))*(.4 + .6*swell);
    const fl2 = Math.sin(T*(1.7 + q*.63) + f.ph*1.4)*(.16 + .34*EN);
    push(); translate(lx, ly); rotate(sg*(1.05 + fl2) + .25);
    if (mode === 1) { noStroke(); fill(inkH, 5, 94, 80*AL); }
    else if (mode === 2) { noStroke(); fill(126, 46, 30, 15*AL); }
    else { stroke(inkH, inkS, inkB, 54*AL); strokeWeight(Math.max(.5, R*.009));
      fill(mode===3?96:104, 46 - wilt*14, mode===3?26:(34 - wilt*6), 78*AL); }
    beginShape(); vertex(0,0); bezierVertex(LL*.3,-LL*.30, LL*.76,-LL*.26, LL,0);
    bezierVertex(LL*.76, LL*.26, LL*.3, LL*.30, 0, 0); endShape(CLOSE);
    pop();
  }

  // --- petals, back-to-front
  const order = [];
  for (let k=0;k<NP;k++) order.push(k);
  order.sort((p, q) => Math.sin(spin + p*6.2832/NP) - Math.sin(spin + q*6.2832/NP));
  for (let oi2=0; oi2<NP; oi2++) {
    const k = order[oi2];
    const phi = spin + k*6.2832/NP;
    const cf = Math.cos(phi), sf = Math.sin(phi);
    const sh = cl((shedP*1.35 - f.shed[k % 13]*1.0)*2.4, 0, 1);   // this petal's abscission
    if (sh >= 1) continue;
    // differential growth: adaxial outgrows abaxial -> curvature reverses through zero
    const k0 = 2.55*(1 - o*2.05) - wilt*1.5;
    // petals tremble at ALL times, not only while wilting (the first cut gated this behind
    // (.3 + wilt), so an open flower was a still life)
    const trem = (.35*Math.sin(T*1.7 + phi*2.3) + .22*Math.sin(T*2.63 + phi*1.31 + f.ph))
               * (.25 + .6*EN) * (.55 + .45*wilt);
    const kT = -.55*o - wilt*1.9 + trem;
    const psi0 = 1.5 - o*.62 + wilt*.2;
    const len = R*(.28 + .72*o)*(.35 + .65*swell);
    const wid = R*(.30 + .1*o)*(.4 + .6*swell);
    const xs = [], zs = [];
    let psi = psi0, rr = R*.1, zz = 0;
    for (let q=0;q<=NSG;q++){
      const s = q/NSG;
      xs.push(rr); zs.push(zz);
      const kk = (k0 + kT*s*2.4) / NSG;
      psi += kk;
      rr += Math.cos(psi)*len/NSG; zz += Math.sin(psi)*len/NSG;
    }
    const px = [], py = [];
    for (let side=0; side<2; side++) {
      for (let q=0;q<=NSG;q++){
        const idx = side ? NSG - q : q;
        const s = idx/NSG;
        const w = wprof(s)*wid*(side ? -1 : 1);
        const X3 = xs[idx]*cf - w*sf, Y3 = xs[idx]*sf + w*cf, Z3 = zs[idx];
        px.push(X3); py.push(-Z3*ct + Y3*stl);
      }
    }
    const dropY = sh*sh*u*.5, dropX = sh*breeze*u*.09;
    const lightF = .42 + .58*(.5 + .5*Math.cos(phi - 2.2));       // modeled by azimuth
    const al = (1 - sh)*AL;
    if (mode === 1) { noStroke(); fill(inkH, 3 + (1-lightF)*7, 99 - (1-lightF)*22 - wilt*18, 88*al); }
    else if (mode === 2) { noStroke(); fill(hh, 48, 30, 17*al); }
    else if (mode === 3) { noStroke(); fill(hh, 34 + wilt*16, (12 + 76*lightF)*(1 - wilt*.3), 94*al); }
    else { stroke(inkH, inkS, inkB, 62*al); strokeWeight(Math.max(.5, R*.010));
      fill(hh, (58 - wilt*24)*(.5 + .5*lightF), (44 + 42*lightF)*(1 - wilt*.22), 90*al); }
    push(); translate(dropX, dropY); if (sh>0) rotate(sh*3.2*(k%2?1:-1));
    beginShape();
    for (let q=0;q<px.length;q++) vertex(px[q], py[q]);
    endShape(CLOSE);
    if (mode === 0 || mode === 3) {                        // stipple modelling on the shaded half
      noStroke(); fill(inkH, mode===3?30:inkS, mode===3?6:inkB, (mode===3?26:16)*al);
      for (let q=0;q<11;q++){ const s = .12 + fr(k*5.1 + q*2.7)*.8;
        const w2 = (fr(k*7.3 + q*1.9) - .5)*wprof(s)*wid*1.5;
        const i2 = Math.min(NSG, Math.round(s*NSG));
        const X3 = xs[i2]*cf - w2*sf, Y3 = xs[i2]*sf + w2*cf;
        const sx = X3, sy = -zs[i2]*ct + Y3*stl;
        ellipse(sx, sy, R*.026*(1-lightF+.25), R*.026*(1-lightF+.25)); }
    }
    pop();
  }
  // --- calyx sepals reflexing as it opens
  for (let k=0;k<5;k++){
    const phi = spin*.6 + k*1.2566 + .3;
    const cf = Math.cos(phi), sf = Math.sin(phi);
    const ln = R*(.42 + .1*o)*(.4 + .6*swell), aw = -.35 - o*.75 - wilt*.3;
    const X3 = cf*ln*Math.cos(aw), Y3 = sf*ln*Math.cos(aw), Z3 = ln*Math.sin(aw);
    if (mode === 1) { stroke(inkH, 14, 78, 68*AL); }
    else if (mode === 2) { stroke(118, 44, 60, 22*AL); }
    else { stroke(mode===3?96:100, 48, mode===3?24:32, 72*AL); }
    strokeWeight(Math.max(.9, R*.045)); noFill();
    beginShape(); vertex(0, 0);
    vertex(X3*.55, -Z3*.55*ct + Y3*.55*stl);
    vertex(X3, -Z3*ct + Y3*stl);
    endShape();
  }
  // --- androecium: filaments + anthers, revealed at anthesis, trembling
  const anth = cl((o - .5)*2.4, 0, 1)*(1 - wilt*.8);
  if (anth > .02) {
    const ns = 9 + ((NP*1.3)|0);
    for (let k=0;k<ns;k++){
      const phi = spin*1.4 + k*6.2832/ns, cf = Math.cos(phi), sf = Math.sin(phi);
      const tr = Math.sin(T*(3.1 + (k%5)*.37) + k)*(.05 + .12*EN) + K.pulse*.05*K.intensity;
      const ln = R*(.30 + .1*fr(k*3.3))*anth, lift = .95 + tr;
      const X3 = cf*ln*Math.cos(lift), Y3 = sf*ln*Math.cos(lift), Z3 = ln*Math.sin(lift) + R*.06;
      const ex = X3, ey = -Z3*ct + Y3*stl;
      if (mode === 1) stroke(inkH, 6, 96, 66*AL); else if (mode === 2) stroke(52, 60, 90, 26*AL);
      else stroke(48, 34, mode===3?62:56, 70*AL);
      strokeWeight(Math.max(.6, R*.014)); line(0, R*.02, ex, ey);
      noStroke();
      if (mode === 1) fill(inkH, 0, 100, 88*AL); else if (mode === 2) fill(52, 70, 100, 34*AL);
      else fill(46, 74, mode===3?90:76, 92*AL);
      ellipse(ex, ey, R*.044*anth, R*.031*anth);
    }
  }
  pop();
}
noFill();
blendMode(BLEND);
